const CACHE='nocturne-eclipse-v1.0.0';
const CORE=['./','./index.html','./style.css?v=1.0.0','./main.mjs?v=1.0.0','./model.mjs','./render.mjs','./audio.mjs','./manifest.webmanifest','./icon.svg','./assets/cathedral.webp','./assets/crypt.webp','./assets/belfry.webp','./assets/props.webp','./assets/hero.webp','./assets/enemies.webp','./assets/atlas.json'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(c=>c.addAll(CORE)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('nocturne-eclipse-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(c=>c.put(event.request,copy));}return response;}).catch(()=>caches.match(event.request).then(r=>r||(event.request.mode==='navigate'?caches.match('./index.html'):Response.error()))));});
